fn is_non_prime(n: u64) -> bool {
    // Since n >= 2, start checking from 2.
    // If any k in [2, sqrt(n)] divides n, n is non-prime.
    // Otherwise, n is prime (return false).
    if n == 2 {
        return false; // 2 is prime
    }

    let limit = (n as f64).sqrt() as u64;
    for k in 2..=limit {
        if n % k == 0 {
            return true; // Found a divisor, n is non-prime
        }
    }
    false
}